WITH e AS (SELECT 'p1' AS actor,'a' AS attempt,'onboarding_plan_written' AS event,toDateTime64('2026-01-01 00:00:01.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p1' AS actor,'a' AS attempt,'onboarding_approved' AS event,toDateTime64('2026-01-01 00:00:02.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p1' AS actor,'a' AS attempt,'onboarding_set_up' AS event,toDateTime64('2026-01-01 00:00:04.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p1' AS actor,'a' AS attempt,'onboarding_set_up' AS event,toDateTime64('2026-01-01 00:00:04.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p2' AS actor,'b' AS attempt,'onboarding_plan_written' AS event,toDateTime64('2026-01-01 00:00:01.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p2' AS actor,'b' AS attempt,'onboarding_approved' AS event,toDateTime64('2026-01-01 00:00:03.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p2' AS actor,'b' AS attempt,'onboarding_set_up' AS event,toDateTime64('2026-01-01 00:00:09.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p3' AS actor,'c' AS attempt,'onboarding_plan_written' AS event,toDateTime64('2026-01-01 00:00:01.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p3' AS actor,'c' AS attempt,'onboarding_approved' AS event,toDateTime64('2026-01-01 00:00:01.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p3' AS actor,'c' AS attempt,'onboarding_set_up' AS event,toDateTime64('2026-01-01 00:00:04.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p4' AS actor,'d' AS attempt,'onboarding_plan_written' AS event,toDateTime64('2026-01-01 00:00:01.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p4' AS actor,'e' AS attempt,'onboarding_approved' AS event,toDateTime64('2026-01-01 00:00:02.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p4' AS actor,'e' AS attempt,'onboarding_set_up' AS event,toDateTime64('2026-01-01 00:00:03.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p5' AS actor,'f' AS attempt,'onboarding_plan_written' AS event,toDateTime64('2026-01-01 00:00:01.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p5' AS actor,'f' AS attempt,'onboarding_approved' AS event,toDateTime64('2026-01-01 00:00:02.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p5' AS actor,'g' AS attempt,'onboarding_plan_written' AS event,toDateTime64('2026-01-01 00:00:05.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p5' AS actor,'g' AS attempt,'onboarding_approved' AS event,toDateTime64('2026-01-01 00:00:07.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p5' AS actor,'g' AS attempt,'onboarding_set_up' AS event,toDateTime64('2026-01-01 00:00:10.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p6' AS actor,'h' AS attempt,'onboarding_approved' AS event,toDateTime64('2026-01-01 00:00:01.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p6' AS actor,'h' AS attempt,'onboarding_plan_written' AS event,toDateTime64('2026-01-01 00:00:02.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p6' AS actor,'h' AS attempt,'onboarding_approved' AS event,toDateTime64('2026-01-01 00:00:04.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p6' AS actor,'h' AS attempt,'onboarding_set_up' AS event,toDateTime64('2026-01-01 00:00:08.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p7' AS actor,'i' AS attempt,'onboarding_plan_written' AS event,toDateTime64('2026-01-01 00:00:01.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p7' AS actor,'i' AS attempt,'onboarding_approved' AS event,toDateTime64('2026-01-01 00:00:02.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p8' AS actor,'i' AS attempt,'onboarding_set_up' AS event,toDateTime64('2026-01-01 00:00:03.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p9' AS actor,'j' AS attempt,'onboarding_plan_written' AS event,toDateTime64('2026-01-01 00:00:01.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p9' AS actor,'j' AS attempt,'onboarding_approved' AS event,toDateTime64('2026-01-01 00:00:02.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p9' AS actor,'j' AS attempt,'onboarding_set_up' AS event,toDateTime64('2026-01-01 00:00:03.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p9' AS actor,'k' AS attempt,'onboarding_plan_written' AS event,toDateTime64('2026-01-01 00:00:04.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p9' AS actor,'k' AS attempt,'onboarding_approved' AS event,toDateTime64('2026-01-01 00:00:05.000000',6,'UTC') AS t,true AS eligible UNION ALL SELECT 'p9' AS actor,'k' AS attempt,'onboarding_set_up' AS event,toDateTime64('2026-01-01 00:00:08.000000',6,'UTC') AS t,true AS eligible),
b AS (SELECT DISTINCT actor,attempt,event,t FROM e WHERE eligible),
stages AS (SELECT actor,attempt,arraySort(groupArrayIf(t,event='onboarding_plan_written')) AS a1,arraySort(groupArrayIf(t,event='onboarding_approved')) AS a2,arraySort(groupArrayIf(t,event='onboarding_set_up')) AS a3 FROM b GROUP BY actor,attempt),
firsts AS (SELECT *,arrayElement(a1,1) AS t1 FROM stages WHERE length(a1)>0),
seconds AS (SELECT *,arrayFilter(x -> x>t1,a2) AS later2 FROM firsts),
thirds AS (SELECT *,arrayElement(later2,1) AS t2,arrayFilter(x -> length(later2)>0 AND x>arrayElement(later2,1),a3) AS later3 FROM seconds),
attempts AS (SELECT actor,attempt,t1,t2,arrayElement(later3,1) AS t3,multiIf(length(later3)>0,3,length(later2)>0,2,1) AS depth FROM thirds),
ranked AS (SELECT *,row_number() OVER(PARTITION BY actor ORDER BY depth DESC,t1,t2,t3,attempt) AS choice FROM attempts),
chosen AS (SELECT * FROM ranked WHERE choice=1),
metrics AS (SELECT count() AS n1,countIf(depth>=2) AS n2,countIf(depth>=3) AS n3,arraySort(groupArrayIf(dateDiff('microsecond',t1,t2)/1000000.0,depth>=2)) AS d12,arraySort(groupArrayIf(dateDiff('microsecond',t1,t3)/1000000.0,depth>=3)) AS d13,arraySort(groupArrayIf(dateDiff('microsecond',t2,t3)/1000000.0,depth>=3)) AS d23,countIf((depth>=2 AND t2<=t1) OR (depth>=3 AND t3<=t2)) AS order_violations,count()-uniqExact(actor) AS duplicate_choices FROM chosen),
raw AS (SELECT countIf(event='onboarding_plan_written') AS raw1,countIf(event='onboarding_plan_written' AND eligible) AS eligible1,uniqExactIf(actor,event='onboarding_plan_written' AND eligible) AS actors1,countIf(event='onboarding_approved') AS raw2,countIf(event='onboarding_approved' AND eligible) AS eligible2,uniqExactIf(actor,event='onboarding_approved' AND eligible) AS actors2,countIf(event='onboarding_set_up') AS raw3,countIf(event='onboarding_set_up' AND eligible) AS eligible3,uniqExactIf(actor,event='onboarding_set_up' AND eligible) AS actors3 FROM e)
SELECT raw.*,metrics.n1,metrics.n2,metrics.n3,if(metrics.n2=0,NULL,(arrayElement(metrics.d12,intDiv(metrics.n2+1,2))+arrayElement(metrics.d12,intDiv(metrics.n2+2,2)))/2.0) AS median_d12,if(metrics.n3=0,NULL,(arrayElement(metrics.d13,intDiv(metrics.n3+1,2))+arrayElement(metrics.d13,intDiv(metrics.n3+2,2)))/2.0) AS median_d13,if(metrics.n3=0,NULL,(arrayElement(metrics.d23,intDiv(metrics.n3+1,2))+arrayElement(metrics.d23,intDiv(metrics.n3+2,2)))/2.0) AS median_d23,metrics.order_violations,metrics.duplicate_choices FROM raw CROSS JOIN metrics
